create function public.cineo_studio_report(owner uuid,days integer default 30,sid bigint default null) returns jsonb language plpgsql security invoker set search_path='' as $$
declare start_day date:=(now() at time zone 'America/Sao_Paulo')::date-greatest(1,least(90,days))+1;today date:=(now() at time zone 'America/Sao_Paulo')::date;v bigint;previous bigint;seconds numeric;complete_count bigint;session_count bigint;new_count bigint;return_count bigint;daily jsonb;hourly jsonb;sources jsonb;funnel jsonb;series jsonb;begin days:=greatest(1,least(90,days));
 if sid is not null and not exists(select 1 from public.cineo_shows where id=sid and owner_id=owner) then raise exception 'Produção indisponível';end if;
 select count(*) into v from public.cineo_qualified_views where creator_id=owner and day>=start_day and (sid is null or show_id=sid);
 select count(*) into previous from public.cineo_qualified_views where creator_id=owner and day>=start_day-days and day<start_day and (sid is null or show_id=sid);
 select coalesce(sum(p.watched_ms),0)/1000.0,count(*) filter(where p.finished),count(*) into seconds,complete_count,session_count from public.cineo_view_sessions p join public.cineo_episodes e on e.id=p.episode_id join public.cineo_shows s on s.id=e.show_id where s.owner_id=owner and p.credited and (p.created_at at time zone 'America/Sao_Paulo')::date>=start_day and (sid is null or s.id=sid);
 select count(*) filter(where first_day>=start_day),count(*) filter(where first_day<start_day) into new_count,return_count from (select user_id,min(day) first_day,max(day) last_day from public.cineo_qualified_views where creator_id=owner and user_id is not null and (sid is null or show_id=sid) group by user_id having max(day)>=start_day)x;
 select coalesce(jsonb_agg(x order by day),'[]') into daily from (select d::date as day,count(q.id) views,coalesce(sum(q.rate_cents_per_thousand),0)/1000.0 estimated_cents,(select coalesce(sum(delta),0) from public.cineo_follower_events f where f.creator_id=owner and (f.created_at at time zone 'America/Sao_Paulo')::date=d::date) follower_delta from generate_series(start_day,today,'1 day')d left join public.cineo_qualified_views q on q.creator_id=owner and q.day=d::date and (sid is null or q.show_id=sid) group by d)x;
 select coalesce(jsonb_agg(x),'[]') into hourly from (select extract(isodow from created_at at time zone 'America/Sao_Paulo')::integer weekday,extract(hour from created_at at time zone 'America/Sao_Paulo')::integer as hour,count(*) views from public.cineo_qualified_views where creator_id=owner and day>=start_day and (sid is null or show_id=sid) group by 1,2 order by 3 desc limit 10)x;
 select coalesce(jsonb_agg(x),'[]') into sources from (select source,count(*) views from public.cineo_qualified_views where creator_id=owner and day>=start_day and (sid is null or show_id=sid) group by source order by 2 desc)x;
 select coalesce(jsonb_agg(x),'[]') into series from (select s.id,s.title,s.status,count(q.id) views,coalesce(sum(q.rate_cents_per_thousand),0)/1000.0 estimated_cents from public.cineo_shows s left join public.cineo_qualified_views q on q.show_id=s.id and q.day>=start_day where s.owner_id=owner group by s.id order by 4 desc)x;
 if sid is not null then
  with eps as (select id,title,season,episode_number,row_number() over(order by season,episode_number,id) n from public.cineo_episodes where show_id=sid and review_status='approved' and not hidden),cohort as(select distinct user_id from public.cineo_qualified_views where episode_id=(select id from eps where n=1) and user_id is not null and day>=start_day)
  select coalesce(jsonb_agg(x order by n),'[]') into funnel from (select e.id,e.title,e.n,count(distinct q.user_id) viewers,count(distinct q.user_id) filter(where q.user_id in(select user_id from cohort)) first_episode_cohort,(select count(*) from cohort) cohort_size from eps e left join public.cineo_qualified_views q on q.episode_id=e.id and q.day>=start_day group by e.id,e.title,e.n)x;
 else funnel:='[]';end if;
 return jsonb_build_object('days',days,'since',start_day,'views',v,'previous_views',previous,'change_percent',case when previous=0 then null else round((v-previous)*100.0/previous,1) end,'watched_seconds',seconds,'finished_sessions',complete_count,'qualified_sessions',session_count,'new_viewers',new_count,'returning_viewers',return_count,'followers',(select count(*) from public.cineo_follows where kind='creator' and target=owner::text and user_id<>owner),'daily',daily,'hours',hourly,'sources',sources,'series',series,'funnel',funnel,'alert',case when previous>=20 and v>=previous*1.5 then 'growth' when previous>=20 and v<=previous*.5 then 'drop' else '' end);
end$$;
create function public.cineo_episode_retention(owner uuid,eid bigint,days integer default 30) returns jsonb language sql stable security invoker set search_path='' as $$
select jsonb_build_object('episode_id',eid,'points',coalesce((select jsonb_agg(x order by second) from (select sec as second,count(distinct p.user_id) viewers from public.cineo_watch_spans w join public.cineo_view_sessions p on p.id=w.session_id join public.cineo_episodes e on e.id=p.episode_id join public.cineo_shows s on s.id=e.show_id cross join lateral generate_series(w.from_ms/1000,least(14400,w.to_ms/1000))sec where s.owner_id=owner and e.id=eid and p.created_at>=now()-make_interval(days=>greatest(1,least(90,days))) group by sec)x),'[]'))$$;


do $$declare p record;begin for p in select oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and proname in('cineo_follower_event','cineo_studio_role','cineo_studio_delegate','cineo_studio_new_show','cineo_studio_report','cineo_episode_retention','cineo_review_month','cineo_request_withdrawal','cineo_review_withdrawal','cineo_studio_finance') loop execute format('revoke all on function %s from public,anon,authenticated',p.signature);execute format('grant execute on function %s to service_role',p.signature);end loop;end$$;

